Definition links_only (r r' : meta) : Prop :=
  m_mem r' = m_mem r /\ m_avail r' = m_avail r /\ m_freed r' = m_freed r
  /\ m_last_idx r' = m_last_idx r /\ m_freeable r' = m_freeable r /\ m_sizeclass r' = m_sizeclass r /\ m_maplen r' = m_maplen r.

