Lemma leaf_of_vis_inv {R} o e (k : Z -> Malloc.M R) r :
  leaf_of o (SVis e k) r ->
  match e with
  | EUndef _ => False
  | EPeek p c h => leaf_of o (k (pans_mem o p c h)) r
  | _ => exists z, leaf_of o (k z) r
  end.
